[meta]
name = Harrowmere
ambient = 0.62 0.58 0.62
fog = 0.42 0.46 0.55
fog_range = 12 56
model_range = 40
sky = overcast
torch = 0 0 0 0
start = 20 44 -90
default = ,
edge_top = -0.5
entity_floor = auto

// Harrowmere climbs from its harbour to the cathedral on the hill, a town of sun-warmed sandstone and
// ochre render under terracotta roofs, paved in cobbles and setts. The pier where the morning boat
// puts in, the quay and the market lanes; the Bell Square at the heart of town with the Silent Bell on
// its plinth; the sunken court of the old well (down into the Sunken Keep) east of it, and the watch
// house by the gap in the wall where the green trail leaves for the cave; Brannoc's forge and
// Corvane's hut to the west; the north road winding up past Odrin's house to the gate; and up the
// steps on the hill, the cathedral, where the Enthroned sits at the end of the nave.

